// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        Helper h = new Helper();

        vm.deal(address(h), 1 ether);

        vm.assume(c.tokenBalance(address(h)) == 0);

        vm.prank(address(h));
        h.doAirdrop(address(c));

        uint256 bal = c.tokenBalance(address(h));
        assertTrue(bal == 20);
    }
}

contract Helper {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function doAirdrop(address caddr) external {
        ModifierEntrancy(caddr).airDrop();
    }
}
